window.OVA_CONTENT={"slug":"seccion-04-bioinformatica-y-trazabilidad","title":"Bioinformática y trazabilidad","minutes":45,"summary":"Organiza, compara e interpreta secuencias biológicas con preguntas claras y metadatos confiables.","objective":"Reconocer el alcance de bases de datos y comparaciones de secuencias en decisiones agroindustriales.","stages":[{"eyebrow":"Datos","title":"1. Una secuencia aún no es una conclusión","reading":"Una secuencia es un conjunto ordenado de símbolos que representa nucleótidos. Adquiere significado cuando se verifica su calidad, se compara con referencias y se interpreta frente a una pregunta.","application":"La bioinformática integra biología, informática y estadística para procesar grandes volúmenes de datos.","activity":{"type":"choice","question":"¿Qué convierte datos en información útil?","options":["Una comparación e interpretación contextualizada","El tamaño del archivo por sí solo","La cantidad de letras sin referencia"],"answer":[0],"success":"La pregunta y el método dan sentido a los datos."}},{"eyebrow":"Comparación","title":"2. Lectura básica de similitud","reading":"Comparar secuencias permite reconocer posiciones conservadas y diferentes. Un porcentaje de similitud debe interpretarse con longitud alineada, calidad, cobertura y referencia utilizada.","application":"La actividad formativa simplifica el proceso y no sustituye análisis especializado.","activity":{"type":"order","question":"Ordena una comparación básica.","items":["Revisar calidad","Elegir referencia","Alinear secuencias","Examinar similitudes y diferencias","Interpretar límites"],"answer":[0,1,2,3,4],"success":"La cifra final necesita contexto metodológico."}},{"eyebrow":"Metadatos","title":"3. Datos sobre los datos","reading":"Los metadatos describen organismo, muestra, lugar, fecha, método, lote y responsable. Permiten evaluar pertinencia, reproducibilidad y relación con el proceso.","application":"Una secuencia excelente con metadatos incompletos puede perder gran parte de su valor para trazabilidad.","activity":{"type":"match","question":"Relaciona metadato y pregunta.","pairs":[{"label":"Lote","value":"producto","option":"¿A qué producto corresponde?"},{"label":"Fecha","value":"cuando","option":"¿Cuándo se tomó?"},{"label":"Método","value":"como","option":"¿Cómo se obtuvo?"},{"label":"Referencia","value":"comparacion","option":"¿Con qué se comparó?"}],"answer":["producto","cuando","como","comparacion"],"success":"Los metadatos hacen auditable la evidencia."}},{"eyebrow":"Calidad","title":"4. Límites de una base de datos","reading":"Las bases de datos pueden contener registros de calidad desigual, anotaciones provisionales o cobertura limitada. También pueden cambiar con nuevas evidencias.","application":"Una decisión de alto impacto requiere referencias curadas y revisión especializada.","activity":{"type":"multi","question":"Selecciona precauciones válidas.","options":["Revisar procedencia del registro","Comprobar calidad y cobertura","Usar varias evidencias","Aceptar siempre el primer resultado"],"answer":[0,1,2],"success":"Las bases de datos son herramientas, no autoridades infalibles."}},{"eyebrow":"Caso aplicado","title":"5. Coincidencia parcial","reading":"Una secuencia de una muestra coincide en 92 % con una referencia, pero el fragmento es corto y contiene posiciones ambiguas. La conclusión no debe exceder la calidad disponible.","application":"Conviene revisar la secuencia, ampliar cobertura y consultar criterios de identificación.","activity":{"type":"choice","question":"¿Qué acción es correcta?","options":["Reportar la incertidumbre y obtener mejor evidencia","Declarar identidad definitiva","Eliminar posiciones diferentes"],"answer":[0],"success":"La incertidumbre debe conservarse en la decisión."}}],"number":"04","references":["Cunningham, W. P. et al. (2023). Principios de Ciencias Ambientales. McGraw-Hill.","Smith, T. M. y Smith, R. L. (2007). Ecología. Pearson.","Hardin, J. y Lodolce, J. P. (2024). Becker. El mundo de la célula. Pearson.","Marino Buslje, C. y Parisi, G. (2019). Aprender para predecir: la bioinformática como herramienta de estudio en biología.","Hodson de Jaramillo, E. et al. (2019). La bioeconomía: nuevo marco para el crecimiento sostenible en América Latina."]};